<?php
/** Живые подстановки в черновые юридические страницы. Финальная вычитка — этап 8. */
defined('ABSPATH') || exit;
add_shortcode('ss_document', static function ($attrs) {
    $type = sanitize_key($attrs['type'] ?? 'privacy');
    if (!in_array($type, ['privacy','consent','offer','delivery'], true)) return '';
    $name = esc_html(ss_shop('legal_name','Реквизиты уточняются'));
    $email = esc_html(ss_shop('email','Email уточняется'));
    $address = esc_html(ss_shop('legal_address','Адрес уточняется'));
    $url = esc_url(home_url('/'));
    ob_start();
    echo '<div class="ss-document">';
    if (ss_shop_is_placeholder()) echo '<p class="ss-draft-note">Предварительная редакция. Контакты и реквизиты будут уточнены перед запуском магазина.</p>';
    if ($type === 'privacy') {
        echo '<h2>Оператор и цели обработки</h2><p>Оператор: ' . $name . '. Адрес: ' . $address . '. Контакт для вопросов о персональных данных: ' . $email . '.</p><p>Мы обрабатываем данные для ответа на обращения, оформления, исполнения и учёта заказов, связи с покупателем и выполнения обязанностей, предусмотренных законодательством РФ.</p><h2>Какие данные используются</h2><p>Имя, фамилия, телефон, email, состав и история заказа, сведения, которые вы указываете в сообщении. Технические cookies обеспечивают работу корзины и оформления заказа.</p><h2>Основания и действия</h2><p>Обработка осуществляется на основании согласия, необходимости заключения и исполнения договора с покупателем и предусмотренных законом обязанностей. Возможны сбор, запись, систематизация, накопление, хранение, уточнение, использование, предоставление в необходимых для исполнения заказа случаях, блокирование, удаление и уничтожение данных. Обработка может быть автоматизированной и неавтоматизированной.</p><h2>Хранение и доступ</h2><p>Данные хранятся в течение срока, необходимого для заявленных целей и обязательного учёта. Доступ предоставляется только лицам, которым он нужен для исполнения заказа или обязанности по закону. Рекламные рассылки по этим данным не выполняются.</p><h2>Ваши права</h2><p>Вы можете запросить сведения об обработке, уточнение, блокирование или удаление данных, а также отозвать согласие, направив обращение на ' . $email . '. Если имеются самостоятельные законные основания, обработка может продолжаться после отзыва согласия.</p><h2>Обновление политики</h2><p>Актуальная редакция размещается на этом сайте. Сведения о сервисах аналитики и обработчиках уточняются перед их подключением.</p>';
    } elseif ($type === 'consent') {
        echo '<h2>Самостоятельное согласие</h2><p>Я свободно, своей волей и в своём интересе даю ' . $name . ', адрес: ' . $address . ', согласие на обработку предоставленных мной имени, фамилии, телефона, email и содержания обращения для ответа на мой вопрос и связи по заказу. При отправке отзыва согласие также предоставляется для его рассмотрения и публикации имени и текста отзыва на сайте; телефон и email не публикуются.</p><p>Согласие распространяется на сбор, запись, систематизацию, накопление, хранение, уточнение, использование, блокирование, удаление и уничтожение указанных данных с применением средств автоматизации и без них.</p><h2>Срок и отзыв</h2><p>Согласие действует до достижения цели обработки или его отзыва. Я могу отозвать его обращением на ' . $email . '. Обработка в целях исполнения договора и выполнения обязанностей по закону может осуществляться на самостоятельных основаниях.</p><p>Это согласие не включает рекламную рассылку, публикацию моих данных или их распространение. Я ознакомлен(а) с <a href="' . esc_url(home_url('/privacy-policy/')) . '">политикой конфиденциальности</a>. Согласие выражается отдельным действием — установкой незаполненного заранее флажка в форме.</p>';
    } elseif ($type === 'offer') {
        echo '<h2>Продавец и предмет договора</h2><p>Продавец: ' . $name . '. ИНН: ' . esc_html(ss_shop('inn')) . '. ОГРН / ОГРНИП: ' . esc_html(ss_shop('ogrn')) . '. Адрес: ' . $address . '.</p><p>На сайте ' . $url . ' размещаются предложения о покупке комплектующих для оборудования с ЧПУ. Наименование, комплектация, характеристики и цена товара указаны в карточке и уточняются при подтверждении заказа.</p><h2>Оформление и оплата</h2><p>Покупатель выбирает товар и модель, указывает контактные данные и оформляет заказ. Продавец связывается для подтверждения наличия и готовности к выдаче. Оплата производится при получении. Итоговая сумма отображается перед оформлением заказа.</p><h2>Получение заказа</h2><p>На старте доступен бесплатный самовывоз по адресу ' . esc_html(ss_shop('pickup_address','Адрес уточняется')) . '. Покупатель приезжает после подтверждения готовности заказа и проверяет комплектность и состояние товара при получении.</p><h2>Возврат, гарантия и обращения</h2><p>Права покупателя, сроки и условия отказа от товара, возврата и устранения недостатков определяются применимыми нормами законодательства РФ, включая законодательство о защите прав потребителей. Для обращения напишите на ' . $email . ', указав номер заказа и описание вопроса. Характеристики и условия гарантии конкретного изделия уточняются в карточке и документах изготовителя.</p><h2>Данные покупателя</h2><p>Персональные данные обрабатываются в соответствии с <a href="' . esc_url(home_url('/privacy-policy/')) . '">политикой конфиденциальности</a>. Оформление заказа не означает согласия на рекламные сообщения.</p>';
    } else {
        echo '<h2>Самовывоз</h2><p>Самовывоз бесплатный. Адрес: ' . esc_html(ss_shop('pickup_address','Адрес уточняется')) . '. Город: ' . esc_html(ss_shop('city')) . '.</p><p>' . nl2br(esc_html(ss_shop('hours'))) . '</p><p>' . esc_html(ss_shop('pickup_details','Дождитесь подтверждения готовности заказа.')) . '</p><h2>Оплата при получении</h2><p>Оформите заказ на сайте. После подтверждения готовности заберите и оплатите его в пункте самовывоза. Доступный способ оплаты указан при оформлении.</p><h2>Другие способы доставки</h2><p>На старте доступен самовывоз. О возможности другого способа получения спросите через <a href="' . esc_url(home_url('/contacts/')) . '">форму связи</a>.</p>';
    }
    echo '</div>';
    return ob_get_clean();
});
add_action('woocommerce_init', static function () {
    if (!function_exists('woocommerce_register_additional_checkout_field')) return;
    woocommerce_register_additional_checkout_field([
        'id'=>'soberi-stanok/personal-data-consent',
        'label'=>'Даю согласие на обработку персональных данных для связи по заказу',
        'location'=>'order','type'=>'checkbox','required'=>true,
        'error_message'=>'Подтвердите отдельное согласие на обработку персональных данных.',
        'validate_callback'=>static function ($value) {return $value ? null : new WP_Error('ss_consent_required','Необходимо согласие на обработку персональных данных.');},
    ]);
});
add_filter('woocommerce_checkout_get_value', static function ($value, $input) { return $input === 'ss_pd_consent' ? false : $value; },10,2);
add_action('woocommerce_review_order_before_submit', static function () {
    woocommerce_form_field('ss_pd_consent',['type'=>'checkbox','required'=>true,'label'=>'Даю согласие на обработку персональных данных'],false);
});
add_action('woocommerce_checkout_process', static function () {
    if(empty($_POST['ss_pd_consent'])) wc_add_notice('Подтвердите согласие на обработку персональных данных.','error');
});
add_action('woocommerce_checkout_create_order', static function ($order) {
    if(!empty($_POST['ss_pd_consent'])) $order->update_meta_data('_ss_pd_consent','yes');
});
// Адрес формы синхронно берётся из «Данных магазина», а не из сохранённого шаблона письма.
add_filter('wpcf7_mail_components', static function ($components,$form) {
    if((int)$form->id()===(int)get_option('ss_contact_form_id')) $components['recipient']=ss_shop('email',get_option('admin_email'));
    return $components;
},10,2);
add_filter('woocommerce_product_review_comment_form_args', static function ($args) {
    $args['comment_field'].='<p class="ss-review-consent"><label><input type="checkbox" name="ss_review_consent" value="1" required> Даю <a href="' . esc_url(home_url('/personal-data-consent/')) . '">согласие на обработку персональных данных</a> для рассмотрения и публикации отзыва.</label></p>';
    return $args;
});
add_filter('preprocess_comment',static function($comment) {
    if(get_post_type($comment['comment_post_ID'])==='product' && empty($_POST['ss_review_consent']) && !current_user_can('moderate_comments')) wp_die('Подтвердите согласие на обработку персональных данных.', 'Необходимо согласие', ['response'=>400,'back_link'=>true]);
    return $comment;
});
